"""matplotlib.widgets — interactive widget stubs."""

import sys as _sys


_widgets_warned = set()

def _widgets_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _widgets_warned:
        _widgets_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] widgets.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Widget:
    __getattr__ = _widgets_getattr_fallback
    drawon = True
    eventson = True
    _active = True

    def set_active(self, active): self._active = active
    def get_active(self): return self._active
    def ignore(self, event): return not self._active
    def on_changed(self, func): self._observer = func
    def on_clicked(self, func): self._observer = func
    def on_submit(self, func):  self._observer = func
    def on_select(self, func):  self._observer = func
    def disconnect(self, cid):  pass
    def disconnect_events(self): pass


class AxesWidget(Widget):
    def __init__(self, ax):
        self.ax = ax
        self.cids = []

    def connect_event(self, event, callback):
        pass

    def disconnect_events(self):
        pass


def _register_observer(self, kind, func):
    """Append `func` to the widget's observer registry under `kind` and
    return a connection id (its index in the list)."""
    if not hasattr(self, '_observers'):
        self._observers = {}
    self._observers.setdefault(kind, []).append(func)
    return len(self._observers[kind]) - 1


def _fire_observers(self, kind, *args, **kwargs):
    """Call every registered observer of the given kind."""
    if not getattr(self, 'eventson', True):
        return
    for cb in (self._observers.get(kind, []) if hasattr(self, '_observers') else []):
        if cb is None: continue
        try: cb(*args, **kwargs)
        except Exception as e:
            import sys as _sys
            _sys.__stderr__.write(f'[widget] observer error: {e}\n')


def _disconnect_observer(self, cid):
    """Remove an observer by id (kind-agnostic)."""
    if not hasattr(self, '_observers'):
        return
    for kind, lst in self._observers.items():
        if 0 <= cid < len(lst):
            lst[cid] = None


# Attach the helpers as private methods on Widget so subclasses inherit.
Widget._register_observer = _register_observer
Widget._fire_observers    = _fire_observers
Widget.disconnect         = _disconnect_observer


class Button(AxesWidget):
    def __init__(self, ax, label, image=None, color='0.85', hovercolor='0.95'):
        super().__init__(ax)
        self.label = label
        self.color = color
        self.hovercolor = hovercolor

    def on_clicked(self, func):
        """Register ``func`` to fire on button clicks. Returns a cid."""
        return self._register_observer('clicked', func)


class Slider(AxesWidget):
    def __init__(self, ax, label, valmin, valmax, *, valinit=0.5,
                 valfmt=None, closedmin=True, closedmax=True, slidermin=None,
                 slidermax=None, dragging=True, valstep=None, orientation='horizontal',
                 initcolor='r', track_color='lightblue', handle_style=None, **kwargs):
        super().__init__(ax)
        self.label = label
        self.valmin = valmin
        self.valmax = valmax
        self.val = valinit
        self.valinit = valinit
        self.valstep = valstep
        self.orientation = orientation
        self.valfmt = valfmt
        self.slidermin = slidermin
        self.slidermax = slidermax
        self.closedmin = closedmin
        self.closedmax = closedmax
        self.drag_active = bool(dragging)

    def on_changed(self, func):
        return self._register_observer('changed', func)

    def set_val(self, val):
        """Clamp `val` against [valmin, valmax] / valstep and fire
        observers (matches upstream)."""
        v = float(val)
        if self.valstep:
            v = round((v - self.valmin) / self.valstep) * self.valstep + self.valmin
        if self.closedmin: v = max(v, self.valmin)
        else:              v = max(v, self.valmin + 1e-12)
        if self.closedmax: v = min(v, self.valmax)
        else:              v = min(v, self.valmax - 1e-12)
        self.val = v
        self._fire_observers('changed', v)

    def reset(self):
        self.set_val(self.valinit)


class RangeSlider(Slider):
    def __init__(self, ax, label, valmin, valmax, valinit=None, **kwargs):
        super().__init__(ax, label, valmin, valmax, **kwargs)
        self.val = valinit or (valmin, valmax)

    def set_val(self, val):
        """RangeSlider takes a ``(lo, hi)`` pair."""
        lo, hi = float(val[0]), float(val[1])
        lo = max(self.valmin, min(lo, self.valmax))
        hi = max(self.valmin, min(hi, self.valmax))
        if lo > hi: lo, hi = hi, lo
        self.val = (lo, hi)
        self._fire_observers('changed', (lo, hi))


class TextBox(AxesWidget):
    def __init__(self, ax, label, initial='', color='.95', hovercolor='1',
                 label_pad=.01, textalignment='left'):
        super().__init__(ax)
        self.label = label
        self.text = initial
        self.color = color
        self.hovercolor = hovercolor

    def on_text_change(self, func):
        return self._register_observer('text_change', func)

    def on_submit(self, func):
        return self._register_observer('submit', func)

    def set_val(self, val):
        old = self.text
        self.text = '' if val is None else str(val)
        if self.text != old:
            self._fire_observers('text_change', self.text)

    def begin_typing(self): pass
    def stop_typing(self):
        self._fire_observers('submit', self.text)


class CheckButtons(AxesWidget):
    def __init__(self, ax, labels, actives=None, *, useblit=True,
                 label_props=None, frame_props=None, check_props=None):
        super().__init__(ax)
        self.labels = list(labels)
        self.actives = list(actives) if actives else [False] * len(self.labels)

    def get_status(self):
        return list(self.actives)

    def set_active(self, index):
        if 0 <= index < len(self.actives):
            self.actives[index] = not self.actives[index]
            self._fire_observers('clicked', self.labels[index])

    def on_clicked(self, func):
        return self._register_observer('clicked', func)


class RadioButtons(AxesWidget):
    def __init__(self, ax, labels, active=0, activecolor=None, *,
                 useblit=True, label_props=None, radio_props=None):
        super().__init__(ax)
        self.labels = list(labels)
        self.value_selected = self.labels[active] if self.labels else None
        self.activecolor = activecolor
        self._active_index = active

    def on_clicked(self, func):
        return self._register_observer('clicked', func)

    def set_active(self, index):
        if 0 <= index < len(self.labels):
            self._active_index = index
            self.value_selected = self.labels[index]
            self._fire_observers('clicked', self.value_selected)


