class Lasso(AxesWidget):
    """Free-hand selection lasso. Tracks the cursor path while the
    mouse button is held and invokes ``callback(verts)`` on release."""

    def __init__(self, ax, xy, callback=None, *, useblit=True, props=None):
        super().__init__(ax)
        self.xy = xy
        self.verts = [tuple(xy)]
        self.callback = callback

    def onmove(self, x, y):
        self.verts.append((x, y))

    def onrelease(self):
        if self.callback is not None:
            try:
                self.callback(self.verts)
            except Exception:
                pass


class _SelectorWidget(AxesWidget):
    """Common base for the interactive selector widgets. Holds the
    onselect callback, useblit/visible flags, and a tiny event-state
    helper used by all the rubber-band rectangles."""

    def __init__(self, ax, onselect, *, useblit=False, button=None,
                 state_modifier_keys=None, use_data_coordinates=False):
        super().__init__(ax)
        self.onselect = onselect
        self.useblit = useblit
        self.button = button
        self._state_modifier_keys = state_modifier_keys or {}
        self.use_data_coordinates = use_data_coordinates
        self.visible = True
        self._state = set()

    def add_state(self, key):    self._state.add(key)
    def remove_state(self, key): self._state.discard(key)

    def set_visible(self, visible):
        self.visible = visible

    def get_visible(self):
        return self.visible


class ToolHandles:
    """Markers shown at the corners/edges of an interactive selector
    that the user can grab to resize. The shim only stores their
    coordinates so callers can read them back."""

    def __init__(self, ax, x, y, *, marker='s', marker_props=None,
                 useblit=True):
        self.ax = ax
        self.x = list(x)
        self.y = list(y)
        self.marker = marker

    def set_data(self, pts):
        x, y = pts
        self.x, self.y = list(x), list(y)

    def get_data(self):
        return self.x, self.y

    @property
    def artists(self):
        return ()


class ToolLineHandles(ToolHandles):
    """Resize handles drawn as line segments rather than markers — used
    by SpanSelector where the dragging element is the span edge."""

    def __init__(self, ax, positions, direction='horizontal',
                 line_props=None, useblit=True):
        # Positions are 1-D (the endpoints of the span).
        super().__init__(ax, x=positions, y=positions, useblit=useblit)
        self.direction = direction


class SubplotTool:
    """The "Configure Subplots" GUI widget. Upstream attaches sliders
    to a tiny figure; here we just expose set_<param> methods so any
    headless code that calls them succeeds."""

    def __init__(self, targetfig=None, toolfig=None):
        self.targetfig = targetfig
        self.toolfig = toolfig
        self.left = 0.125
        self.bottom = 0.11
        self.right = 0.9
        self.top = 0.88
        self.wspace = 0.2
        self.hspace = 0.2

    def funcleft(self, val):   self.left = val
    def funcright(self, val):  self.right = val
    def functop(self, val):    self.top = val
    def funcbottom(self, val): self.bottom = val
    def funcwspace(self, val): self.wspace = val
    def funchspace(self, val): self.hspace = val


class MultiCursorTool(MultiCursor):
    """Alias preserved for code referencing the older name. Real
    matplotlib renamed/kept both at various points."""
