# ─── Added: LockDraw + SliderBase from upstream widgets.py ──────────


class LockDraw:
    """A simple cooperative lock used by widgets to coordinate redraws.
    Only one widget may hold the lock at a time; ``available()`` lets
    others check whether they may proceed."""

    def __init__(self):
        self._owner = None

    def __call__(self, owner):
        if self._owner is None:
            self._owner = owner

    def release(self, owner):
        if self._owner is owner:
            self._owner = None

    def available(self, owner):
        return self._owner is None or self._owner is owner

    def isowner(self, owner):
        return self._owner is owner

    def locked(self):
        return self._owner is not None


class SliderBase(AxesWidget):
    """Shared base of :class:`Slider` and :class:`RangeSlider`. Holds the
    common state (label, value range, orientation, optional valstep)
    plus the no-op connect/disconnect/reset surface that subclasses
    customise."""

    def __init__(self, ax, orientation, closedmin, closedmax, valmin, valmax,
                 valfmt, dragging, valstep):
        super().__init__(ax)
        self.orientation = orientation
        self.closedmin = closedmin
        self.closedmax = closedmax
        self.valmin = valmin
        self.valmax = valmax
        self.valfmt = valfmt
        self.drag_active = False
        self.valstep = valstep
        self._observers = []

    def disconnect(self, cid):
        if 0 <= cid < len(self._observers):
            self._observers[cid] = None

    def reset(self):
        pass

    def _stepped_value(self, val):
        if self.valstep is None:
            return val
        return self.valmin + round((val - self.valmin) / self.valstep) * self.valstep


# ─── Added: ToolLineHandles + RectangleSelector helpers ─────────────


def _tlh_closest(self, x, y):
    """Return the index of the handle closest to (x, y)."""
    if not self.x:
        return None
    best, d_best = 0, float('inf')
    for i, (hx, hy) in enumerate(zip(self.x, self.y)):
        d = (hx - x) ** 2 + (hy - y) ** 2
        if d < d_best:
            d_best, best = d, i
    return best
def _tlh_positions(self):  return list(zip(self.x, self.y))
def _tlh_direction(self):  return self.direction
def _tlh_remove(self):     self.x = self.y = []
def _tlh_set_animated(self, b): self._animated = bool(b)

ToolLineHandles.closest      = _tlh_closest
ToolLineHandles.positions    = property(_tlh_positions)
ToolLineHandles.direction    = property(_tlh_direction)
ToolLineHandles.remove       = _tlh_remove
ToolLineHandles.set_animated = _tlh_set_animated


# RectangleSelector
def _rs_center_get(self):
    e = self.extents
    return ((e[0] + e[1]) / 2, (e[2] + e[3]) / 2)
def _rs_corners_get(self):
    x0, x1, y0, y1 = self.extents
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
def _rs_edge_centers_get(self):
    x0, x1, y0, y1 = self.extents
    xc, yc = (x0 + x1) / 2, (y0 + y1) / 2
    return [(xc, y0), (x1, yc), (xc, y1), (x0, yc)]
def _rs_extents_get(self): return getattr(self, '_extents', (0.0, 1.0, 0.0, 1.0))
def _rs_extents_set(self, e): self._extents = tuple(e)
def _rs_geometry_get(self):
    return ((self.extents[0], self.extents[1]),
            (self.extents[2], self.extents[3]))
def _rs_rotation_get(self): return getattr(self, '_rotation', 0.0)
def _rs_rotation_set(self, r): self._rotation = float(r)

RectangleSelector.center       = property(_rs_center_get)
RectangleSelector.corners      = property(_rs_corners_get)
RectangleSelector.edge_centers = property(_rs_edge_centers_get)
RectangleSelector.extents      = property(_rs_extents_get, _rs_extents_set)
RectangleSelector.geometry     = property(_rs_geometry_get)
RectangleSelector.rotation     = property(_rs_rotation_get, _rs_rotation_set)


