def _th_closest(self, x, y):
    if not self.x: return None
    best, d_best = 0, float('inf')
    for i, (hx, hy) in enumerate(zip(self.x, self.y)):
        d = (hx - x) ** 2 + (hy - y) ** 2
        if d < d_best:
            d_best, best = d, i
    return best
def _th_set_animated(self, b): self._animated = bool(b)
def _th_set_visible(self, b):  self._visible = bool(b)

ToolHandles.closest      = _th_closest
